Unit Test Code:
#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_slice_negative_to_and_cap_to_len(void) {
    // Setup: create a buffer with known data
    buffer_t *src = helper_make_buffer_with_data("abcdefg"); // len = 7

    // Choose from and to:
    // from = 2 ("c"), to = -1 (should be interpreted as len - ~(-1) = 7 - 0 = 7)
    // But let's also test capping: to = 10 (greater than len), so it should be capped to 7
    // We'll test both cases in one: negative to, and to > len after conversion

    size_t from = 2;
    ssize_t to = -1; // ~(-1) = 0, so to = 7 - 0 = 7

    // Test: call buffer_slice
    buffer_t *slice = buffer_slice(src, from, to);

    // Assertions
    TEST_ASSERT_NOT_NULL(slice);
    // The expected data is from index 2 up to 7: "cdefg"
    helper_assert_buffer_data_equals(slice, "cdefg");
    helper_assert_buffer_length(slice, 5);

    // Cleanup
    buffer_free(src);
    buffer_free(slice);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_slice_negative_to_and_cap_to_len);
    return UNITY_END();
}

