    size_t actual_length = buffer_length(buf);
    TEST_ASSERT_EQUAL_UINT64(expected_length, actual_length);
}

// Asserts that the buffer's allocated size matches the expected value.
void helper_assert_buffer_size(buffer_t *buf, size_t expected_size) {
    size_t actual_size = buffer_size(buf);
    TEST_ASSERT_EQUAL_UINT64(expected_size, actual_size);
}

