void helper_assert_buffer_is_empty(buffer_t *buf) {
    TEST_ASSERT_EQUAL_UINT64(0, buffer_length(buf));
}

// ========== Created - Utility Operations ==========

// Creates a new buffer with a copy of the given string data.
buffer_t *helper_make_buffer_with_data(char *str) {
    return buffer_new_with_copy(str);
}

// Creates a new buffer with a given size and copies the string data into it.
buffer_t *helper_make_buffer_with_data_and_size(char *str, size_t size) {
    buffer_t *buf = buffer_new_with_size(size);
    if (buf && str) {
        size_t copy_len = strlen(str);
        if (copy_len >= size) copy_len = size - 1;
        memcpy(buf->data, str, copy_len);
        buf->data[copy_len] = '\0';
        buf->length = copy_len; // FIX: update buffer's length field
    } else if (buf) {
        buf->data[0] = '\0';
        buf->length = 0; // Also set length to 0 if no data
    }
    return buf;
}


